function guard_out_dir(out_dir, mode)
% GUARD_OUT_DIR  (CN-009) never overwrite: a dataset folder that already holds records is refused.
    if isfolder(out_dir) && ~isempty(dir(fullfile(out_dir, '*.mat')))
        error('cn:outDirNotEmpty', 'Output folder already contains .mat records (mode %s):\n  %s', mode, out_dir);
    end
end
EOF
echo ok

